CREATE TABLE IF NOT EXISTS app_users(id VARCHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,app_role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER');
CREATE TABLE IF NOT EXISTS wallets(owner_id VARCHAR(36) PRIMARY KEY REFERENCES app_users(id),points INTEGER NOT NULL DEFAULT 0 CHECK(points>=0),spend DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(spend>=0));
CREATE TABLE IF NOT EXISTS campaign_versions(id VARCHAR(36),version INTEGER,name VARCHAR(80) NOT NULL,code VARCHAR(30) NOT NULL,segment VARCHAR(10) NOT NULL,starts_at VARCHAR(40) NOT NULL,ends_at VARCHAR(40) NOT NULL,min_spend DECIMAL(12,2) NOT NULL,discount_percent INTEGER NOT NULL,points_per_ten INTEGER NOT NULL,max_uses INTEGER NOT NULL,PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS campaigns(id VARCHAR(36) PRIMARY KEY,version INTEGER NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS purchases(id VARCHAR(36) PRIMARY KEY,owner_id VARCHAR(36) NOT NULL REFERENCES app_users(id),request_key VARCHAR(80) NOT NULL,fingerprint VARCHAR(300) NOT NULL,gross DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL,net DECIMAL(12,2) NOT NULL,earned INTEGER NOT NULL,redeemed INTEGER NOT NULL,campaign_id VARCHAR(36),campaign_version INTEGER,status VARCHAR(20) NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE(owner_id,request_key));
CREATE TABLE IF NOT EXISTS points_ledger(id VARCHAR(36) PRIMARY KEY,owner_id VARCHAR(36) NOT NULL REFERENCES app_users(id),purchase_id VARCHAR(36) NOT NULL REFERENCES purchases(id),kind VARCHAR(20) NOT NULL,delta INTEGER NOT NULL,balance_after INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(36) NOT NULL REFERENCES app_users(id),action VARCHAR(30) NOT NULL,resource_id VARCHAR(36) NOT NULL,detail VARCHAR(200) NOT NULL,created_at VARCHAR(40) NOT NULL);

CREATE TABLE IF NOT EXISTS rule_mutex(id INTEGER PRIMARY KEY);
INSERT INTO rule_mutex(id) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM rule_mutex WHERE id=1);
